+import React, { useEffect, useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Field from '../../elements/Field';
+import Spinner from '../../elements/Spinner';
+import Heading from '../../typography/Heading';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [isEditing, setIsEditing] = useState(false);
+    const [name, setName] = useState('');
+    const [savedName, setSavedName] = useState<{ deviceId: string, name: string }>();
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string>();
+    const displayName = savedName?.deviceId === device.device_id ? savedName.name : device.display_name;
+
+    useEffect(() => {
+        setSavedName(undefined);
+    }, [device.device_id, device.display_name]);
+
+    const onRename = (): void => {
+        setName(displayName ?? '');
+        setError(undefined);
+        setIsEditing(true);
+    };
+
+    const onCancel = (): void => {
+        setError(undefined);
+        setIsEditing(false);
+    };
+
+    const onSave = async (event: React.FormEvent): Promise<void> => {
+        event.preventDefault();
+        if (isSaving) return;
+        if (name === displayName) {
+            setIsEditing(false);
+            return;
+        }
+        setIsSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, name);
+            setSavedName({ deviceId: device.device_id, name });
+            setIsEditing(false);
+        } catch (error) {
+            setError(_t('Failed to set display name.'));
+        } finally {
+            setIsSaving(false);
+        }
+    };
+
+    if (isEditing) {
+        return <form onSubmit={onSave} data-testid='device-detail-heading-edit'>
+            <Field
+                label={_t('Session name')}
+                value={name}
+                maxLength={100}
+                onChange={event => setName(event.target.value.slice(0, 100))}
+                autoFocus
+                data-testid='device-detail-heading-input'
+            />
+            <p>{ _t('Session names may be visible to other people you communicate with.') }</p>
+            { error && <p role='alert' data-testid='device-detail-heading-error'>{ error }</p> }
+            <button type='submit' disabled={isSaving} data-testid='device-detail-heading-save'>
+                { _t('Save') }
+            </button>
+            <button type='button' onClick={onCancel} disabled={isSaving} data-testid='device-detail-heading-cancel'>
+                { _t('Cancel') }
+            </button>
+            { isSaving && <span role='status' data-testid='device-detail-heading-saving'>
+                <Spinner w={16} h={16} />
+            </span> }
+        </form>;
+    }
+
+    return <div data-testid='device-detail-heading-read'>
+        <Heading size='h3'>{ displayName ?? device.device_id }</Heading>
+        <AccessibleButton kind='link_inline' onClick={onRename} data-testid='device-detail-heading-rename'>
+            { _t('Rename') }
+        </AccessibleButton>
+    </div>;
+};
